	if (!owner) {
		error = new Constants.Error.Error("Connect your public identity", "This instance's user directory requires a connected identity bound to an account. Manage your public identity in Settings, then search again.");
		isMounted = true; return;
	}
	void (async () => {
		try { await onSearch(); }
		catch (cause) {
			if (directoryDisposed || revision !== directoryEpoch) return;
			error = cause instanceof Constants.Error.Error ? cause : Constants.Error.Unknown;
		}
		if (!directoryDisposed && revision === directoryEpoch) isMounted = true;
	})();
});

